// Events — fire and forget
class NavVM : ViewModel() {
  private val _events = MutableSharedFlow<NavEvent>(
    extraBufferCapacity = 8,
    onBufferOverflow = BufferOverflow.DROP_OLDEST
  )
  val events: SharedFlow<NavEvent> = _events.asSharedFlow()
  fun signOut() { _events.tryEmit(NavEvent.SignOut) }
}

// Cold repository flow → hot screen state
val users: StateFlow<List<User>> =
  repository.usersFlow
    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())

// SharingStarted strategies
// - Eagerly: starts at once, runs until the scope dies
// - Lazily: starts on the first collector, never stops
// - WhileSubscribed(5_000): survives a rotation, stops when the screen is gone

// Cooperative cancellation
suspend fun longCompute() = withContext(Dispatchers.Default) {
  repeat(1_000_000) { i ->
    if (i % 1000 == 0) ensureActive()  // throws CancellationException if cancelled
    // work...
  }
}

// Cleanup that must run even on cancellation
suspend fun saveAndQuit() = coroutineScope {
  try {
    longRunning()
  } finally {
    withContext(NonCancellable) {
      flush()                          // runs even after cancellation
    }
  }
}

// Don't swallow CancellationException
suspend fun bad() {
  try { longRunning() }
  catch (e: Throwable) { log(e) }       // ⚠️ eats cancellation
}
suspend fun alsoBad() {
  runCatching { longRunning() }          // ⚠️ same trap
    .onFailure { log(it) }
}
suspend fun good() {
  try {
    longRunning()
  } catch (e: CancellationException) {
    throw e                              // ✅ re-throw first
  } catch (e: Throwable) {
    log(e)
  }
}

// CoroutineExceptionHandler — root scope, launch only
val handler = CoroutineExceptionHandler { _, e -> Logger.error(e) }
val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO + handler)

// async — the failure surfaces at await(), not at launch
val deferred = scope.async { failingCall() }
try { deferred.await() } catch (e: Throwable) { /* handle */ }
